selector_to_html = {"a[href=\"#types\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Types<a class=\"headerlink\" href=\"#types\" title=\"Link to this heading\">#</a></h2><p>By default, valid commit types include:</p>", "a[href=\"#commit-messages\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Messages<a class=\"headerlink\" href=\"#commit-messages\" title=\"Link to this heading\">#</a></h1><p>Since stakeholders are the ultimate audience of a\n<a class=\"reference external\" href=\"https://en.wikipedia.org/wiki/changelog#\">changelog</a>, good commit messages do not merely\nrecapitulate the diff but rather explain why we modified something.</p>", "a[href=\"../style/markdown.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Markdown Style Guide<a class=\"headerlink\" href=\"#markdown-style-guide\" title=\"Link to this heading\">#</a></h1><p>Follow the\n<a class=\"reference external\" href=\"https://google.github.io/styleguide/docguide/style.html\">Google Markdown style guide</a>,\nbut use a more traditional 70-character line limit.  Use two spaces\nafter sentence-ending punctuation.</p>", "a[href=\"#unscoped-changes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Unscoped Changes<a class=\"headerlink\" href=\"#unscoped-changes\" title=\"Link to this heading\">#</a></h2><p>This includes changes instigated by code in top-level OpenTofu\nresource definitions like <code class=\"docutils literal notranslate\"><span class=\"pre\">main.tf</span></code> or in second-level Python\n<a class=\"reference external\" href=\"https://wiki.python.org/moin/DunderAlias\">dunder</a> modules such as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">src/example/__init__.py</span></code>.  This also includes integration, system, or\nacceptance test changes.</p>", "a[href=\"#scopes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Scopes<a class=\"headerlink\" href=\"#scopes\" title=\"Link to this heading\">#</a></h2><p>An <a class=\"reference internal\" href=\"atomic.html\"><span class=\"doc std std-doc\">atomic commit</span></a> can alter multiple files.  Per\n<em>Conventional Commits</em>, a commit scope is an optional abbreviation,\nacronym, codename, or keyword that provides additional context to\nreviewers by naming the essential component of the change.  For\nexample, an interface change would require modifications to method\ncalls or property references throughout the codebase, so the commit\nscope would be the module containing the class definition.</p><p>By default, scope commits as follows:</p>", "a[href=\"#syntax\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Syntax<a class=\"headerlink\" href=\"#syntax\" title=\"Link to this heading\">#</a></h2><p>This facilitates automatic changelog generation.  For example, refer\nto <a class=\"github reference external\" href=\"https://github.com/ResearchDataCom/good-devops-practice/blob/v1.1.0/CHANGELOG.md#\">this document\u2019s changelog</a>.</p>", "a[href=\"#formatting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Formatting<a class=\"headerlink\" href=\"#formatting\" title=\"Link to this heading\">#</a></h2><p>Refer the <a class=\"reference internal\" href=\"../style/markdown.html\"><span class=\"doc std std-doc\">Markdown style guide</span></a> for further\nformatting guidance.</p>", "a[href=\"atomic.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Atomic Commits<a class=\"headerlink\" href=\"#atomic-commits\" title=\"Link to this heading\">#</a></h1><p>Commit frequently but with purpose.  This naturally results in clear\nand concise\u2014but not necessarily short\u2014commits that make code\nreviews more efficient.  Refer to\n<a class=\"reference external\" href=\"https://www.aleksandrhovhannisyan.com/blog/atomic-git-commits/\">\u201cMake Atomic Git Commits\u201d</a>\nand <a class=\"reference external\" href=\"https://nrempel.com/blog/atomic-commits/\">\u201cAtomic Commits\u201d</a> for\nadditional guidance.</p>", "a[href=\"#descriptions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Descriptions<a class=\"headerlink\" href=\"#descriptions\" title=\"Link to this heading\">#</a></h2><p>Each commit\u2019s description becomes a bullet point in a report\nsummarizing the changes incorporated in a specific release.</p>", "a[href=\"#language\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Language<a class=\"headerlink\" href=\"#language\" title=\"Link to this heading\">#</a></h2><p>Regardless of the language, commit messages should be otherwise\ngrammatically correct.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
